struct Cli {
    #[clap(short = 'f', help = "the file in which bartib tracks all the activities", env = "BARTIB_FILE")]
    file: Option<PathBuf>,

    #[clap(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    Start {
