        #[clap(long, help = "begin of date range (inclusive)")]
        from: Option<String>,
        #[clap(long, help = "end of date range (inclusive)")]
        to: Option<String>,
        #[clap(short, long, help = "do list activities for this project only")]
        project: Option<String>,
        #[clap(short, long, help = "maximum number of activities to display")]
        number: Option<usize>,
        #[clap(long, help = "rounds the start and end time to the nearest duration. Durations can be in minutes or hours. E.g. 15m or 4h")]
        round: Option<String>,
        #[clap(long, help = "do not group activities by date in list")]
        no_grouping: bool,
    },
    Report {
        #[clap(long, help = "show activities of the current day")]
        today: bool,
        #[clap(long, help = "show yesterdays' activities")]
        yesterday: bool,
        #[clap(long, help = "show activities of the current week")]
        current_week: bool,
        #[clap(long, help = "show activities of the last week")]
        last_week: bool,
        #[clap(short, long, help = "show activities of a certain date only")]
        date: Option<String>,
        #[clap(long, help = "begin of date range (inclusive)")]
        from: Option<String>,
        #[clap(long, help = "end of date range (inclusive)")]
        to: Option<String>,
        #[clap(short, long, help = "do report activities for this project only")]
        project: Option<String>,
        #[clap(long, help = "rounds the start and end time to the nearest duration. Durations can be in minutes or hours. E.g. 15m or 4h")]
        round: Option<String>,
    },
    Status {
        #[clap(short, long, help = "show status for this project only")]
        project: Option<String>,
    },
    Current,
    Last,
    Search {
        #[clap(default_value = "", help = "the search term")]
        search_term: String,
    },
    Cancel,
    Change {
        #[clap(short, long, help = "the description of the new activity")]
        description: Option<String>,
        #[clap(short, long, help = "the project to which the new activity belongs")]
        project: Option<String>,
        #[clap(short, long, help = "the time for changing the activity status (HH:MM)")]
        time: Option<String>,
    },
    Check,
    Sanity,
    Projects,
    Edit,
