#[derive(Debug, Clone)]
struct Activity {
    start: NaiveDateTime,
    end: Option<NaiveDateTime>,
    project: String,
    description: String,
    line_number: usize,
}

fn unescape(s: &str) -> String {
    let mut result = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(&next) = chars.peek() {
                if next == '|' || next == '\\' {
                    result.push(next);
                    chars.next();
                    continue;
                }
            }
        }
        result.push(c);
    }
    result
}

fn escape(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        if c == '|' || c == '\\' {
            result.push('\\');
        }
        result.push(c);
    }
    result
}

fn parse_activity(line: &str, line_number: usize) -> Option<Activity> {
    let parts: Vec<&str> = line.split(" | ").collect();
    if parts.len() < 3 { return None; }

    let time_part = parts[0];
    let project = unescape(parts[1]);
    let description = unescape(parts[2]);

    let (start_str, end_str) = if time_part.contains(" - ") {
        let t: Vec<&str> = time_part.split(" - ").collect();
        (t[0], Some(t[1]))
    } else {
        (time_part, None)
    };

    let start = NaiveDateTime::parse_from_str(start_str, "%Y-%m-%d %H:%M").ok()?;
    let end = if let Some(e) = end_str {
        Some(NaiveDateTime::parse_from_str(e, "%Y-%m-%d %H:%M").ok()?)
    } else {
        None
    };

    Some(Activity {
        start,
        end,
        project,
        description,
        line_number,
    })
}

fn format_duration(d: Duration) -> String {
    if d.num_seconds() < 60 {
        return "<1m".to_string();
    }
    let minutes = d.num_minutes() % 60;
    let hours = d.num_hours();
    if hours > 0 {
        format!("{}h {:02}m", hours, minutes)
    } else {
        format!("{:02}m", minutes)
    }
}

fn main() {
    let cli = Cli::parse();
    let file_path = if let Some(f) = cli.file {
        f
    } else {
        eprintln!("Error: Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable");
        std::process::exit(1);
    };

    // ... handle subcommands ...
}
EOF
