                if next == '|' || next == '\\' {
                    result.push(next);
                    chars.next();
                    continue;
                }
            }
        }
        result.push(c);
    }
    result
}

fn escape(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        if c == '|' || c == '\\' { result.push('\\'); }
        result.push(c);
    }
    result
}

fn parse_activity(line: &str, line_index: usize) -> Option<Activity> {
    let parts: Vec<&str> = line.split(" | ").collect();
    if parts.len() < 3 { return None; }
    let (start_str, end_str) = if parts[0].contains(" - ") {
        let t: Vec<&str> = parts[0].split(" - ").collect();
        (t[0], Some(t[1]))
    } else {
        (parts[0], None)
    };
    let start = NaiveDateTime::parse_from_str(start_str, "%Y-%m-%d %H:%M").ok()?;
    let end = end_str.map(|e| NaiveDateTime::parse_from_str(e, "%Y-%m-%d %H:%M").ok()).flatten();
    Some(Activity {
        start,
        end,
        project: unescape(parts[1]),
        description: unescape(parts[2]),
        line_index,
    })
}

fn format_duration(d: Duration) -> String {
    let mins = d.num_minutes();
    if mins < 1 { return "<1m".to_string(); }
    let h = mins / 60;
    let m = mins % 60;
    if h > 0 { format!("{}h {:02}m", h, m) } else { format!("{:02}m", m) }
}

fn round_time(t: NaiveDateTime, round: &Option<String>) -> NaiveDateTime {
    let round_str = match round {
        Some(s) => s,
        None => return t,
    };
    let minutes = if round_str.ends_with('m') {
        round_str[..round_str.len()-1].parse::<i64>().unwrap_or(1)
    } else if round_str.ends_with('h') {
        round_str[..round_str.len()-1].parse::<i64>().unwrap_or(1) * 60
    } else {
        1
    };
    let secs = minutes * 60;
    let ts = t.timestamp();
    let rounded = ((ts + secs / 2) / secs) * secs;
    NaiveDateTime::from_timestamp(rounded, 0)
}

fn get_file_path(cli_file: Option<PathBuf>) -> PathBuf {
    if let Some(f) = cli_file { return f; }
    if let Ok(f) = env::var("BARTIB_FILE") { return PathBuf::from(f); }
    eprintln!("Error: Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable");
    std::process::exit(1);
}

fn load_lines(path: &PathBuf) -> Vec<String> {
    if !path.exists() { return Vec::new(); }
    let file = File::open(path).expect("Could not open file");
    BufReader::new(file).lines().map(|l| l.unwrap()).collect()
}

fn get_date_range(cli: &Commands) -> (Option<NaiveDate>, Option<NaiveDate>) {
    let now = Local::now().naive_local().date();
    match cli {
        Commands::List { today, yesterday, current_week, last_week, date, from, to, .. } |
        Commands::Report { today, yesterday, current_week, last_week, date, from, to, .. } => {
            if *today { return (Some(now), Some(now)); }
            if *yesterday { let y = now - Duration::days(1); return (Some(y), Some(y)); }
            if *current_week {
                let weekday = now.weekday().num_days_from_monday();
                let start = now - Duration::days(weekday as i64);
                return (Some(start), Some(now));
            }
            if *last_week {
                let weekday = now.weekday().num_days_from_monday();
                let start = now - Duration::days(weekday as i64 + 7);
                let end = start + Duration::days(6);
                return (Some(start), Some(end));
            }
            if let Some(d) = date {
                let d = NaiveDate::parse_from_str(d, "%Y-%m-%d").expect("Could not parse date");
                return (Some(d), Some(d));
            }
            let f = from.as_ref().map(|s| NaiveDate::parse_from_str(s, "%Y-%m-%d").expect("Could not parse from date"));
            let t = to.as_ref().map(|s| NaiveDate::parse_from_str(s, "%Y-%m-%d").expect("Could not parse to date"));
            (f, t)
        }
        _ => (None, None),
    }
}

fn filter_activities(activities: &[Activity], start_date: Option<NaiveDate>, end_date: Option<NaiveDate>, project: &Option<String>) -> Vec<Activity> {
    activities.iter().filter(|a| {
        if let Some(sd) = start_date { if a.start.date() < sd { return false; } }
        if let Some(ed) = end_date { if a.start.date() > ed { return false; } }
        if let Some(p) = project { if &a.project != p { return false; } }
        true
    }).cloned().collect()
}

fn main() {
    let cli = Cli::parse();
    let file_path = get_file_path(cli.file);
    let mut lines = load_lines(&file_path);
    let mut activities: Vec<Activity> = Vec::new();
    for (i, line) in lines.iter().enumerate() {
        if let Some(a) = parse_activity(line, i) {
            activities.push(a);
        }
    }

    match cli.command {
        Commands::Start { description, project, time } => {
            let now = Local::now().naive_local();
            let start_time = if let Some(t) = time {
                let time_parsed = NaiveTime::parse_from_str(&t, "%H:%M").expect("Could not parse time");
                now.date().and_time(time_parsed)
            } else { now.with_second(0).unwrap().with_nanosecond(0).unwrap() };

            for a in &mut activities {
                if a.end.is_none() {
                    a.end = Some(start_time);
                    let duration = a.end.unwrap() - a.start;
                    println!("Stopped activity: \"{}\" ({}) started at {} ({})", a.description, a.project, a.start.format("%Y-%m-%d %H:%M"), format_duration(duration));
                    lines[a.line_index] = format!("{} - {} | {} | {}", a.start.format("%Y-%m-%d %H:%M"), a.end.unwrap().format("%Y-%m-%d %H:%M"), escape(&a.project), escape(&a.description));
                }
            }
            println!("Started activity: \"{}\" ({}) at {}", description, project, start_time.format("%Y-%m-%d %H:%M"));
            lines.push(format!("{} | {} | {}", start_time.format("%Y-%m-%d %H:%M"), escape(&project), escape(&description)));
            let mut f = File::create(&file_path).unwrap();
            for line in lines { writeln!(f, "{}", line).unwrap(); }
        }
        Commands::Stop { time } => {
            let now = Local::now().naive_local();
            let stop_time = if let Some(t) = time {
                let time_parsed = NaiveTime::parse_from_str(&t, "%H:%M").expect("Could not parse time");
                now.date().and_time(time_parsed)
            } else { now.with_second(0).unwrap().with_nanosecond(0).unwrap() };
            let mut found = false;
            for a in &mut activities {
                if a.end.is_none() {
                    a.end = Some(stop_time);
                    let duration = a.end.unwrap() - a.start;
                    println!("Stopped activity: \"{}\" ({}) started at {} ({})", a.description, a.project, a.start.format("%Y-%m-%d %H:%M"), format_duration(duration));
                    lines[a.line_index] = format!("{} - {} | {} | {}", a.start.format("%Y-%m-%d %H:%M"), a.end.unwrap().format("%Y-%m-%d %H:%M"), escape(&a.project), escape(&a.description));
                    found = true;
                }
            }
            if found {
                let mut f = File::create(&file_path).unwrap();
                for line in lines { writeln!(f, "{}", line).unwrap(); }
            }
        }
        Commands::Continue { number, description, project, time } => {
            let unique = {
                let mut u = Vec::new();
                let mut seen = BTreeSet::new();
                for a in activities.iter().rev() {
                    if !seen.contains(&(a.description.clone(), a.project.clone())) {
                        seen.insert((a.description.clone(), a.project.clone()));
                        u.push((a.description.clone(), a.project.clone()));
                    }
                }
                u
            };
            if let Some((d, p)) = unique.get(number) {
                let desc = description.unwrap_or(d.clone());
                let proj = project.unwrap_or(p.clone());
                // Call start logic
                let now = Local::now().naive_local();
                let start_time = if let Some(t) = time {
                    let time_parsed = NaiveTime::parse_from_str(&t, "%H:%M").expect("Could not parse time");
                    now.date().and_time(time_parsed)
                } else { now.with_second(0).unwrap().with_nanosecond(0).unwrap() };
                for a in &mut activities {
                    if a.end.is_none() {
                        a.end = Some(start_time);
                        let duration = a.end.unwrap() - a.start;
                        println!("Stopped activity: \"{}\" ({}) started at {} ({})", a.description, a.project, a.start.format("%Y-%m-%d %H:%M"), format_duration(duration));
                        lines[a.line_index] = format!("{} - {} | {} | {}", a.start.format("%Y-%m-%d %H:%M"), a.end.unwrap().format("%Y-%m-%d %H:%M"), escape(&a.project), escape(&a.description));
                    }
                }
                println!("Started activity: \"{}\" ({}) at {}", desc, proj, start_time.format("%Y-%m-%d %H:%M"));
                lines.push(format!("{} | {} | {}", start_time.format("%Y-%m-%d %H:%M"), escape(&proj), escape(&desc)));
                let mut f = File::create(&file_path).unwrap();
                for line in lines { writeln!(f, "{}", line).unwrap(); }
            }
        }
        Commands::List { ref round, project: ref proj_filter, number, no_grouping, .. } => {
            let (sd, ed) = get_date_range(&cli.command);
            let mut filtered = filter_activities(&activities, sd, ed, proj_filter);
            if let Some(n) = number { filtered = filtered.into_iter().rev().take(n).rev().collect(); }
            if filtered.is_empty() { println!("No activity to display"); return; }

            let d_width = filtered.iter().map(|a| a.description.len()).max().unwrap_or(11).max(11);
            let p_width = filtered.iter().map(|a| a.project.len()).max().unwrap_or(7).max(7);

            println!("\n{} {} {} {} {}", "Started".underline(), "Stopped".underline(), format!("{:<width$}", "Description", width=d_width).underline(), format!("{:<width$}", "Project", width=p_width).underline(), "Duration".underline());

            let mut current_date: Option<NaiveDate> = None;
            for a in filtered {
                if !no_grouping && (sd.is_none() || ed != sd) {
                   if current_date != Some(a.start.date()) {
                       current_date = Some(a.start.date());
                       let day_total: Duration = activities.iter().filter(|x| x.start.date() == current_date.unwrap()).map(|x| {
                           let s = round_time(x.start, round);
                           let e = round_time(x.end.unwrap_or(Local::now().naive_local().with_second(0).unwrap().with_nanosecond(0).unwrap()), round);
                           e - s
                       }).fold(Duration::zero(), |acc, d| acc + d);
                       println!("\n{}", format!("{}\t{}", current_date.unwrap(), format_duration(day_total)).bold());
                   }
                }
                let s_rounded = round_time(a.start, round);
                let e_now = Local::now().naive_local().with_second(0).unwrap().with_nanosecond(0).unwrap();
                let e_rounded = a.end.map(|e| round_time(e, round)).unwrap_or(round_time(e_now, round));
                let duration = e_rounded - s_rounded;

                let line = format!("{:02}:{:02}   {:02}:{:02}   {:<d_width$} {:<p_width$} {}", 
                    s_rounded.hour(), s_rounded.minute(),
                    if a.end.is_some() { format!("{:02}:{:02}", e_rounded.hour(), e_rounded.minute()) } else { "-".to_string() + "      " }[..5].to_string(),
                    a.description, a.project, format_duration(duration),
                    d_width=d_width, p_width=p_width);

                if a.end.is_none() { println!("{}", line.green()); } else { println!("{}", line); }
            }
        }
        Commands::Report { ref round, project: ref proj_filter, .. } => {
            let (sd, ed) = get_date_range(&cli.command);
            let filtered = filter_activities(&activities, sd, ed, proj_filter);
            let mut projects: BTreeMap<String, BTreeMap<String, Duration>> = BTreeMap::new();
            let mut total_duration = Duration::zero();

            for a in filtered {
                let s = round_time(a.start, round);
                let e = a.end.map(|e| round_time(e, round)).unwrap_or(round_time(Local::now().naive_local().with_second(0).unwrap().with_nanosecond(0).unwrap(), round));
                let d = e - s;
                *projects.entry(a.project.clone()).or_default().entry(a.description.clone()).or_default() += d;
                total_duration = total_duration + d;
            }

            println!("");
            for (proj, tasks) in projects {
                let proj_total: Duration = tasks.values().cloned().fold(Duration::zero(), |acc, d| acc + d);
                let label = format!("{} ", proj);
                let dur_str = format_duration(proj_total);
                let dots = if 36 > label.len() + dur_str.len() { ".".repeat(36 - label.len() - dur_str.len()) } else { " ".to_string() };
                println!("{}", format!("{}{}{}", label, dots, dur_str).bold());
                for (task, duration) in tasks {
                    let task_label = format!("    {} ", task);
                    let task_dur_str = format_duration(duration);
                    let task_dots = if 36 > task_label.len() + task_dur_str.len() { ".".repeat(36 - task_label.len() - task_dur_str.len()) } else { " ".to_string() };
                    println!("{}{}{}", task_label, task_dots, task_dur_str);
                }
                println!("");
            }
            let total_label = "Total ";
            let total_dur_str = format_duration(total_duration);
            let total_dots = if 36 > total_label.len() + total_dur_str.len() { ".".repeat(36 - total_label.len() - total_dur_str.len()) } else { " ".to_string() };
            println!("{}", format!("{}{}{}", total_label, total_dots, total_dur_str).bold());
            println!("");
        }
        Commands::Last => {
            let unique = {
                let mut u = Vec::new();
                let mut seen = BTreeSet::new();
                for a in activities.iter().rev() {
                    if !seen.contains(&(a.description.clone(), a.project.clone())) {
                        seen.insert((a.description.clone(), a.project.clone()));
                        u.push((a.description.clone(), a.project.clone()));
                    }
                }
                u
            };
            println!("\n{} {} {}", " # ".underline(), "Description".underline(), "Project  ".underline());
            for (i, (d, p)) in unique.iter().enumerate() {
                println!("[{}] {:<11} {:<7}", i, d, p);
            }
        }
        Commands::Projects => {
            let mut projs: BTreeSet<String> = activities.iter().map(|a| a.project.clone()).collect();
            for p in projs { println!("\"{}\"", p); }
        }
        _ => { eprintln!("Not fully implemented"); }
    }
