import sys, os, argparse, subprocess, re
from datetime import datetime, timedelta, date, time

def unescape(s): return s.replace('\\|', '|').replace('\\\\', '\\')
def escape(s): return s.replace('\\', '\\\\').replace('|', '\\|')

class Activity:
    def __init__(self, start, end, project, description, line_index):
        self.start, self.end, self.project, self.description, self.line_index = start, end, project, description, line_index

def parse_activity(line, index):
    parts = line.split(' | ')
    if len(parts) < 3: return None
    time_part, project, description = parts[0], unescape(parts[1]), unescape(parts[2])
    try:
        if ' - ' in time_part:
            s_str, e_str = time_part.split(' - ')
            return Activity(datetime.strptime(s_str, '%Y-%m-%d %H:%M'), datetime.strptime(e_str, '%Y-%m-%d %H:%M'), project, description, index)
        return Activity(datetime.strptime(time_part, '%Y-%m-%d %H:%M'), None, project, description, index)
    except: return None

def format_duration(td):
    mins = int(td.total_seconds()) // 60
    if mins < 1: return "<1m"
    h, m = divmod(mins, 60)
    return f"{h}h {m:02}m" if h > 0 else f"{m:02}m"

def round_time(dt, round_min):
    if not round_min or dt is None: return dt
    secs = round_min * 60
    return datetime.fromtimestamp(int((dt.timestamp() + secs / 2) // secs) * secs)

def get_file_path(args):
    f = args.file or os.environ.get('BARTIB_FILE')
    if not f:
        print("Error: Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable", file=sys.stderr)
        sys.exit(1)
    return f

def load_activities(path):
    if not os.path.exists(path): return [], []
    with open(path, 'r') as f: lines = [l.strip('\n') for l in f]
    return lines, [a for a in (parse_activity(l, i) for i, l in enumerate(lines)) if a]

def save_lines(path, lines):
    with open(path, 'w') as f:
        for l in lines: f.write(l + '\n')

def get_date_range(args):
    now = datetime.now().date()
    if getattr(args, 'today', False): return now, now
    if getattr(args, 'yesterday', False):
        y = now - timedelta(days=1)
        return y, y
    if getattr(args, 'current_week', False):
        return now - timedelta(days=now.weekday()), now
    if getattr(args, 'last_week', False):
        s = now - timedelta(days=now.weekday() + 7)
        return s, s + timedelta(days=6)
    if getattr(args, 'date', None):
        d = datetime.strptime(args.date, '%Y-%m-%d').date()
        return d, d
    return (datetime.strptime(args.from_date, '%Y-%m-%d').date() if getattr(args, 'from_date', None) else None,
            datetime.strptime(args.to_date, '%Y-%m-%d').date() if getattr(args, 'to_date', None) else None)

def main():
    parser = argparse.ArgumentParser(prog='bartib')
    parser.add_argument('-f', '--file')
    subparsers = parser.add_subparsers(dest='command')
    for cmd in ['start', 'stop', 'continue', 'list', 'report', 'status', 'current', 'last', 'search', 'cancel', 'change', 'check', 'sanity', 'projects', 'edit']:
        p = subparsers.add_parser(cmd)
        if cmd in ['start', 'continue', 'change']:
            p.add_argument('-d', '--description', required=(cmd=='start'))
            p.add_argument('-p', '--project', required=(cmd=='start'))
        if cmd in ['start', 'stop', 'continue', 'change']: p.add_argument('-t', '--time')
        if cmd == 'continue': p.add_argument('number', type=int, nargs='?', default=0)
        if cmd in ['list', 'report']:
            p.add_argument('--today', action='store_true'); p.add_argument('--yesterday', action='store_true')
            p.add_argument('--current_week', action='store_true'); p.add_argument('--last_week', action='store_true')
            p.add_argument('-d', '--date'); p.add_argument('--from', dest='from_date'); p.add_argument('--to', dest='to_date')
            p.add_argument('-p', '--project'); p.add_argument('--round')
        if cmd == 'list': p.add_argument('-n', '--number', type=int); p.add_argument('--no_grouping', action='store_true')
        if cmd == 'search': p.add_argument('search_term', nargs='?', default='')
        if cmd == 'status': p.add_argument('-p', '--project')

    args = parser.parse_args()
    if not args.command: return
    path = get_file_path(args)
    lines, acts = load_activities(path)
    now = datetime.now().replace(second=0, microsecond=0)
    round_min = getattr(args, 'round', None)
    if round_min:
        if round_min.endswith('m'): round_min = int(round_min[:-1])
        elif round_min.endswith('h'): round_min = int(round_min[:-1]) * 60

    if args.command in ['start', 'stop', 'continue', 'change']:
        t = now
        if args.time: t = datetime.combine(now.date(), datetime.strptime(args.time, '%H:%M').time())

        if args.command == 'stop' or args.command == 'start' or args.command == 'continue':
            for a in [a for a in acts if a.end is None]:
                a.end = t
                lines[a.line_index] = f"{a.start.strftime('%Y-%m-%d %H:%M')} - {a.end.strftime('%Y-%m-%d %H:%M')} | {escape(a.project)} | {escape(a.description)}"
                print(f"Stopped activity: \"{a.description}\" ({a.project}) started at {a.start.strftime('%Y-%m-%d %H:%M')} ({format_duration(a.end - a.start)})")

        if args.command == 'start':
            lines.append(f"{t.strftime('%Y-%m-%d %H:%M')} | {escape(args.project)} | {escape(args.description)}")
            print(f"Started activity: \"{args.description}\" ({args.project}) at {t.strftime('%Y-%m-%d %H:%M')}")
        elif args.command == 'continue':
            unique = []
            seen = set()
            for a in reversed(acts):
                if (a.description, a.project) not in seen:
                    unique.append((a.description, a.project))
                    seen.add((a.description, a.project))
            if args.number < len(unique):
                d, p = unique[args.number]
                desc, proj = args.description or d, args.project or p
                lines.append(f"{t.strftime('%Y-%m-%d %H:%M')} | {escape(proj)} | {escape(desc)}")
                print(f"Started activity: \"{desc}\" ({proj}) at {t.strftime('%Y-%m-%d %H:%M')}")
        elif args.command == 'change':
            for a in [a for a in acts if a.end is None]:
                a.description = args.description or a.description
                a.project = args.project or a.project
                lines[a.line_index] = f"{a.start.strftime('%Y-%m-%d %H:%M')} | {escape(a.project)} | {escape(a.description)}"
                print(f"Changed activity: \"{a.description}\" ({a.project}) started at {a.start.strftime('%Y-%m-%d %H:%M')}")
        save_lines(path, lines)

    elif args.command == 'list':
        sd, ed = get_date_range(args)
        filtered = [a for a in acts if (sd is None or a.start.date() >= sd) and (ed is None or a.start.date() <= ed) and (not args.project or a.project == args.project)]
        if args.number: filtered = filtered[-args.number:]
        if not filtered: print("No activity to display"); return
        dw, pw = max([len(a.description) for a in filtered] + [11]), max([len(a.project) for a in filtered] + [7])
        print(f"\n\033[4mStarted\033[0m \033[4mStopped\033[0m \033[4m{'Description':<{dw}}\033[0m \033[4m{'Project':<{pw}}\033[0m \033[4mDuration\033[0m")
        cur_date = None
        for a in filtered:
            if not args.no_grouping and (sd != ed or sd is None):
                if a.start.date() != cur_date:
                    cur_date = a.start.date()
                    total = sum((round_time(x.end or now, round_min) - round_time(x.start, round_min) for x in acts if x.start.date() == cur_date), timedelta())
                    print(f"\n\033[1m{cur_date}\t{format_duration(total)}\033[0m")
            s, e = round_time(a.start, round_min), round_time(a.end or now, round_min)
            line = f"{s.strftime('%H:%M')}   {e.strftime('%H:%M') if a.end else '-    '}   {a.description:<{dw}} {a.project:<{pw}} {format_duration(e-s)}"
            print(f"\033[32m{line}\033[0m" if not a.end else line)

    elif args.command == 'report':
        sd, ed = get_date_range(args)
        filtered = [a for a in acts if (sd is None or a.start.date() >= sd) and (ed is None or a.start.date() <= ed) and (not args.project or a.project == args.project)]
        projects = {}
        for a in filtered:
            dur = round_time(a.end or now, round_min) - round_time(a.start, round_min)
            p = projects.setdefault(a.project, {'total': timedelta(), 'tasks': {}})
            p['tasks'][a.description] = p['tasks'].get(a.description, timedelta()) + dur
            p['total'] += dur

        max_label_len = 0
        for p, data in projects.items():
            max_label_len = max(max_label_len, len(p), *(len(t) + 4 for t in data['tasks']))
        max_label_len = max(max_label_len, 5) # "Total"
        total_width = max(36, max_label_len + 1 + 6)

        print("")
        for p in sorted(projects.keys()):
            label, dur_str = p + " ", format_duration(projects[p]['total'])
            dots = "." * (total_width - len(label) - len(dur_str) - 1)
            print(f"\033[1m{label}{dots}. {dur_str}\033[0m")
            for t in sorted(projects[p]['tasks'].keys()):
                label, dur_str = "    " + t + " ", format_duration(projects[p]['tasks'][t])
                dots = "." * (total_width - len(label) - len(dur_str) - 1)
                print(f"{label}{dots} {dur_str}")
            print("")
        total_dur = sum((p['total'] for p in projects.values()), timedelta())
        label, dur_str = "Total ", format_duration(total_dur)
        dots = "." * (total_width - len(label) - len(dur_str) - 1)
        print(f"\033[1m{label}{dots}. {dur_str}\033[0m\n")

    elif args.command == 'projects':
        for p in sorted(list(set(a.project for a in acts))): print(f'"{p}"')
    elif args.command in ['last', 'search']:
        term = getattr(args, 'search_term', '').lower()
        unique = []
        seen = set()
        for a in reversed(acts):
            if term in a.description.lower() or term in a.project.lower():
                if (a.description, a.project) not in seen:
                    unique.append((a.description, a.project)); seen.add((a.description, a.project))
        print(f"\n\033[4m # \033[0m \033[4mDescription\033[0m \033[4mProject  \033[0m")
        for i, (d, p) in enumerate(unique): print(f"[{i}] {d:<11} {p:<7}")
    elif args.command == 'cancel':
        for a in reversed([a for a in acts if a.end is None]):
            print(f"Canceled activity: \"{a.description}\" ({a.project}) started at {a.start.strftime('%Y-%m-%d %H:%M')}")
            lines.pop(a.line_index)
        save_lines(path, lines)
    elif args.command == 'current':
        running = [a for a in acts if a.end is None]
        if not running: return
        print(f"\n\033[4mStarted At      \033[0m \033[4mDescription\033[0m \033[4mProject  \033[0m \033[4mDuration\033[0m")
        for a in running: print(f"{a.start.strftime('%Y-%m-%d %H:%M')} {a.description:<11} {a.project:<8} {format_duration(now-a.start)}")
    elif args.command == 'status':
        p_filter = args.project
        def get_total(sd, ed): return sum(((a.end or now) - a.start for a in acts if (not p_filter or a.project == p_filter) and sd <= a.start.date() <= ed), timedelta())
        today = now.date()
        t_today, t_week, t_month = get_total(today, today), get_total(today - timedelta(days=today.weekday()), today), get_total(today.replace(day=1), today)
        now_act = next((a for a in acts if a.end is None and (not p_filter or a.project == p_filter)), None)
        print(f"\033[2m\n =======\033[0m\033[3m Status for {'project: ' + p_filter if p_filter else 'ALL projects'} \033[0m\033[2m ======= \033[0m")
        if now_act: print(f"\033[2;3m\n  NOW: \033[0m\033[1;32m{now_act.description}\033[0m\033[2;3m on \033[0m\033[3m{now_act.project}\033[0m\033[2m ...... \033[0m\033[1m{format_duration(now-now_act.start)}\033[0m")
        else: print(f"\033[2;3m\n  NOW: \033[0m\033[1m NO Activity\n")
        for l, t in [("Today", t_today), ("Current week", t_week), ("Current month", t_month)]:
            dots = "." * (30 - len(l))
            print(f"\033[3m \033[0m\033[2;3m {l}{dots} \033[0m\033[1m{format_duration(t)}\033[0m\033[3m\033[0m")
        print("\033[3m\n\033[0m")
    elif args.command == 'check':
        errors = []
        with open(path, 'r') as f:
            for i, l in enumerate(f):
                if l.strip() and not parse_activity(l.strip(), i): errors.append((l.strip(), i+1))
        if errors:
            print(f"Found {len(errors)} line(s) with parsing errors\n")
            for l, n in errors: print(f"{l}\n  -> could not parse activity (Line: {n})")
        else: print("All lines in the file have been successfully parsed as activities.")
    elif args.command == 'sanity':
        overlaps = [acts[i+1] for i in range(len(acts)-1) if acts[i].end and acts[i].end > acts[i+1].start]
        if overlaps:
            for a in overlaps: print(f"Activity started before another activity ended\n{a.description} (Started: {a.start.strftime('%Y-%m-%d %H:%M')}, Ended: {a.end.strftime('%Y-%m-%d %H:%M') if a.end else '-'}, Line: {a.line_index+1})\n")
        else: print("No unusual activities.")
    elif args.command == 'edit':
        subprocess.call([os.environ.get('EDITOR', 'vi'), path])

if __name__ == '__main__': main()
