        for a in running: print(f"{a.start.strftime('%Y-%m-%d %H:%M')} {a.description:<11} {a.project:<8} {format_duration(now-a.start)}")
    elif args.command == 'status':
        p_filter = args.project
        def get_total(sd, ed): return sum(((a.end or now) - a.start for a in acts if (not p_filter or a.project == p_filter) and sd <= a.start.date() <= ed), timedelta())
        today = now.date()
        t_today, t_week, t_month = get_total(today, today), get_total(today - timedelta(days=today.weekday()), today), get_total(today.replace(day=1), today)
        now_act = next((a for a in acts if a.end is None and (not p_filter or a.project == p_filter)), None)
        print(f"\033[2m\n =======\033[0m\033[3m Status for {'project: ' + p_filter if p_filter else 'ALL projects'} \033[0m\033[2m ======= \033[0m")
        if now_act: print(f"\033[2;3m\n  NOW: \033[0m\033[1;32m{now_act.description}\033[0m\033[2;3m on \033[0m\033[3m{now_act.project}\033[0m\033[2m ...... \033[0m\033[1m{format_duration(now-now_act.start)}\033[0m")
        else: print(f"\033[2;3m\n  NOW: \033[0m\033[1m NO Activity\n")
        for l, t in [("Today", t_today), ("Current week", t_week), ("Current month", t_month)]:
            dots = "." * (30 - len(l))
            print(f"\033[3m \033[0m\033[2;3m {l}{dots} \033[0m\033[1m{format_duration(t)}\033[0m\033[3m\033[0m")
        print("\033[3m\n\033[0m")
    elif args.command == 'check':
        errors = []
        with open(path, 'r') as f:
            for i, l in enumerate(f):
                if l.strip() and not parse_activity(l.strip(), i): errors.append((l.strip(), i+1))
        if errors:
            print(f"Found {len(errors)} line(s) with parsing errors\n")
            for l, n in errors: print(f"{l}\n  -> could not parse activity (Line: {n})")
        else: print("All lines in the file have been successfully parsed as activities.")
    elif args.command == 'sanity':
        overlaps = [acts[i+1] for i in range(len(acts)-1) if acts[i].end and acts[i].end > acts[i+1].start]
        if overlaps:
            for a in overlaps: print(f"Activity started before another activity ended\n{a.description} (Started: {a.start.strftime('%Y-%m-%d %H:%M')}, Ended: {a.end.strftime('%Y-%m-%d %H:%M') if a.end else '-'}, Line: {a.line_index+1})\n")
        else: print("No unusual activities.")
    elif args.command == 'edit':
        subprocess.call([os.environ.get('EDITOR', 'vi'), path])

if __name__ == '__main__': main()
